CREATE TABLE loans (loan_id VARCHAR2(16) PRIMARY KEY, customer_id VARCHAR2(16) NOT NULL, product VARCHAR2(32) NOT NULL, principal NUMBER(18,2) NOT NULL, interest_rate NUMBER(5,2) NOT NULL, term_months NUMBER(3) NOT NULL, origination_ts TIMESTAMP WITH TIME ZONE NOT NULL, status VARCHAR2(16) NOT NULL);
CREATE TABLE repayments (repayment_id VARCHAR2(16) PRIMARY KEY, loan_id VARCHAR2(16) NOT NULL REFERENCES loans(loan_id), payment_ts TIMESTAMP WITH TIME ZONE NOT NULL, amount NUMBER(18,2) NOT NULL, status VARCHAR2(16) NOT NULL);
